def _two_sided_p(stats, obs, total):
    """Two-sided p-value: 2x the one-sided tail in the direction of ``obs``.

    Ties at the observed value belong to the observed tail; if the other
    tail is empty the observed tail is used. Result is capped at 1.
    """
    le = int(np.sum(stats <= obs))
    ge = int(np.sum(stats >= obs))
    tail = min(le, ge)
    if tail == 0:
        tail = max(le, ge)
    return min(1.0, 2.0 * tail / total)


